/**
 * Таймер до момента `target`, считается по серверным часам.
 *
 * Когда остаток доходит до нуля, компонент не меняет состояние распродажи сам,
 * а зовёт `onElapsed` — решение о смене статуса принимает сервер.
 */

import { useEffect } from 'react'

import { useServerClock } from './ServerClockContext'

interface CountdownProps {
  target: string
  label: string
  onElapsed?: () => void
}

function formatRemaining(ms: number): string {
  const totalSeconds = Math.max(0, Math.floor(ms / 1000))
  const days = Math.floor(totalSeconds / 86400)
  const hours = Math.floor((totalSeconds % 86400) / 3600)
  const minutes = Math.floor((totalSeconds % 3600) / 60)
  const seconds = totalSeconds % 60

  const pad = (value: number) => String(value).padStart(2, '0')
  const clock = `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`
  return days > 0 ? `${days} д ${clock}` : clock
}

export function Countdown({ target, label, onElapsed }: CountdownProps) {
  const { nowMs } = useServerClock()
  const remainingMs = new Date(target).getTime() - nowMs
  const elapsed = remainingMs <= 0

  useEffect(() => {
    if (elapsed) onElapsed?.()
  }, [elapsed, onElapsed])

  return (
    <div className="countdown">
      <span className="countdown__label">{label}</span>
      <span className="countdown__value">{formatRemaining(remainingMs)}</span>
    </div>
  )
}

