:root {
  --bg: #0f1115;
  --surface: #171a21;
  --surface-hover: #1e222b;
  --border: #272c37;
  --text: #e8eaf0;
  --muted: #9aa3b2;
  --accent: #4c8dff;
  --accent-ink: #ffffff;
  --upcoming: #c99a2e;
  --active: #2fa36b;
  --ended: #6b7280;
  --danger: #e5484d;

  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  line-height: 1.5;
}

h1 {
  font-size: 1.6rem;
  margin: 0 0 0.75rem;
}

a {
  color: inherit;
  text-decoration: none;
}

code {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.1em 0.35em;
  font-size: 0.85em;
}

.app {
  min-height: 100vh;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
}

.header__brand {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
}

.header__nav {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.header__user {
  color: var(--muted);
  font-size: 0.9rem;
}

.main {
  max-width: 1000px;
  margin: 0 auto;
  padding: 1.5rem;
}

.muted {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0.35rem 0;
}

.error {
  color: var(--danger);
  margin: 0.5rem 0;
}

.notice {
  border-left: 3px solid var(--accent);
  padding-left: 0.75rem;
  color: var(--muted);
  margin: 0.75rem 0 0;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1rem;
}

.card {
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  transition: background 0.15s ease, transform 0.15s ease;
}

.card:hover {
  background: var(--surface-hover);
  transform: translateY(-2px);
}

.card__image {
  width: 100%;
  aspect-ratio: 3 / 2;
  object-fit: cover;
}

.card__body {
  padding: 1rem;
}

.card__title {
  font-size: 1.05rem;
  margin: 0.5rem 0 0.25rem;
}

.card__price {
  font-weight: 600;
  margin: 0.25rem 0;
}

