  margin: 2rem auto;
}

.back {
  color: var(--muted);
  font-size: 0.9rem;
}

.sale {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 1.5rem;
  margin-top: 1rem;
}

