  .sale {
    grid-template-columns: 1fr;
  }
}

.sale__image {
  width: 100%;
  border-radius: 10px;
  object-fit: cover;
}

.sale__price {
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0.75rem 0;
}

.badge {
  display: inline-block;
  padding: 0.15rem 0.6rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #0f1115;
}

.badge--upcoming {
  background: var(--upcoming);
}

.badge--active {
  background: var(--active);
}

.badge--ended {
  background: var(--ended);
  color: var(--text);
}

.stock {
  margin: 1rem 0;
}

.stock__bar {
  height: 8px;
  border-radius: 999px;
  background: var(--border);
  overflow: hidden;
}

.stock__fill {
  height: 100%;
  background: var(--active);
  transition: width 0.3s ease;
}

.countdown {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
  margin: 1rem 0;
}

.countdown__label {
  color: var(--muted);
  font-size: 0.9rem;
}

.countdown__value {
  font-size: 1.75rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.meta {
  display: flex;
  gap: 2rem;
  margin: 1rem 0;
}

.meta dt {
  color: var(--muted);
  font-size: 0.8rem;
}

.meta dd {
  margin: 0;
  font-size: 0.9rem;
}

.form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-top: 1rem;
}

.form__field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  font-size: 0.9rem;
  color: var(--muted);
}

input {
  padding: 0.6rem 0.75rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  font: inherit;
}

input:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.button {
  padding: 0.6rem 1.1rem;
  border-radius: 8px;
  border: 1px solid transparent;
  background: var(--accent);
  color: var(--accent-ink);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.15s ease;
}

.button:hover:not(:disabled) {
  opacity: 0.9;
}

.button:disabled {
  background: var(--border);
  color: var(--muted);
  cursor: not-allowed;
}

.button--ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--text);
  font-weight: 500;
}

.button--buy {
  width: 100%;
  margin-top: 0.5rem;
  padding: 0.8rem 1.1rem;
  font-size: 1rem;
}

