import { useCallback, useEffect, useState } from 'react'

import { ApiError, api } from '../api'
import type { Sale } from '../api'

interface SaleState {
  sale: Sale | null
  error: string | null
  loading: boolean
  refetch: () => Promise<void>
}

function messageOf(cause: unknown): string {
  return cause instanceof ApiError ? cause.message : 'Не удалось загрузить распродажу'
}

export function useSale(saleId: string): SaleState {
  const [sale, setSale] = useState<Sale | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)

  const refetch = useCallback(async () => {
    try {
      setSale(await api.getSale(saleId))
      setError(null)
    } catch (cause) {
      setError(messageOf(cause))
    } finally {
      setLoading(false)
    }
  }, [saleId])

  useEffect(() => {
    setLoading(true)
    void refetch()
  }, [refetch])

  return { sale, error, loading, refetch }
}

export function useSalesList() {
  const [sales, setSales] = useState<Sale[] | null>(null)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    api
      .listSales()
      .then((loaded) => {
        if (!cancelled) setSales(loaded)
      })
      .catch((cause: unknown) => {
        if (!cancelled) setError(messageOf(cause))
      })
    return () => {
      cancelled = true
    }
  }, [])

  return { sales, error }
}

