import { useCallback, useEffect, useState } from 'react'
import { Link, useParams } from 'react-router-dom'

import { useAuth } from '../auth/AuthContext'
import { STATUS_LABELS, formatDateTime, formatMoney } from '../format'
import { Countdown } from '../time/Countdown'
import { useServerClock } from '../time/ServerClockContext'
import { useSale } from './useSale'

export function SalePage() {
  const { saleId = '' } = useParams()
  const { sale, error, loading, refetch } = useSale(saleId)
  const { synced } = useServerClock()
  const { user } = useAuth()

  // Таймер дошёл до нуля — ждём, что скажет сервер.
  const [awaitingServer, setAwaitingServer] = useState(false)
  const [reserveNotice, setReserveNotice] = useState(false)

  const handleElapsed = useCallback(() => setAwaitingServer(true), [])

  // Опрашиваем раз в секунду, пока сервер не сменит статус. Одного запроса
  // недостаточно: при расхождении часов в доли секунды сервер ещё отдаёт
  // прежний статус, и локальный таймер тут же снова покажет ноль.
  useEffect(() => {
    if (!awaitingServer) return
    const timer = setInterval(() => {
      void refetch()
    }, 1000)
    return () => clearInterval(timer)
  }, [awaitingServer, refetch])

  // Статус сменился — опрос больше не нужен.
  useEffect(() => {
    setAwaitingServer(false)
  }, [sale?.status])

  if (loading) return <p className="muted">Загружаем…</p>
  if (error !== null) return <p className="error">{error}</p>
  if (sale === null) return null

  const soldOut = sale.remaining === 0
  const canBuy = sale.status === 'active' && !soldOut

  return (
    <article className="panel">
      <Link to="/" className="back">
        ← Все распродажи
      </Link>

      <div className="sale">
        {sale.product_image_url !== null && (
          <img className="sale__image" src={sale.product_image_url} alt="" />
        )}

        <div className="sale__info">
          <span className={`badge badge--${sale.status}`}>{STATUS_LABELS[sale.status]}</span>
          <h1>{sale.product_name}</h1>
          {sale.product_description !== null && (
            <p className="muted">{sale.product_description}</p>
          )}

          <p className="sale__price">{formatMoney(sale.price_minor, sale.currency)}</p>

          <div className="stock">
            <div className="stock__bar">
              <div
                className="stock__fill"
                style={{ width: `${(sale.remaining / sale.quantity) * 100}%` }}
              />
            </div>
            <p className="muted">
              Осталось {sale.remaining} из {sale.quantity}
            </p>
          </div>

          {sale.status === 'upcoming' && (
            <Countdown target={sale.start_at} label="До старта" onElapsed={handleElapsed} />
          )}
          {sale.status === 'active' && (
            <Countdown target={sale.end_at} label="До конца" onElapsed={handleElapsed} />
          )}

          {awaitingServer && <p className="muted">Уточняем статус у сервера…</p>}

          <dl className="meta">
            <div>
              <dt>Старт</dt>
              <dd>{formatDateTime(sale.start_at)}</dd>
            </div>
            <div>
              <dt>Конец</dt>
              <dd>{formatDateTime(sale.end_at)}</dd>
            </div>
          </dl>

          <button
            type="button"
            className="button button--buy"
            disabled={!canBuy}
            onClick={() => setReserveNotice(true)}
          >
            Купить
          </button>

          {!canBuy && (
            <p className="muted">
              {soldOut
                ? 'Всё разобрали'
                : sale.status === 'upcoming'
                  ? 'Кнопка включится, когда распродажа начнётся'
                  : 'Распродажа завершена'}
            </p>
          )}
          {reserveNotice && <p className="notice">Резерв — на следующем шаге.</p>}
          {user === null && canBuy && <p className="muted">Для покупки понадобится вход.</p>}
          {!synced && <p className="muted">Серверное время недоступно, таймер приблизительный.</p>}
        </div>
      </div>
    </article>
  )
}

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'

import { ApiError } from '../api'
import { useAuth } from './AuthContext'

export function LoginPage() {
  const { login } = useAuth()
  const navigate = useNavigate()
  const [email, setEmail] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [pending, setPending] = useState(false)

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    setError(null)
    setPending(true)
    try {
      await login(email)
      navigate('/')
    } catch (cause) {
      setError(cause instanceof ApiError ? cause.message : 'Не удалось войти')
    } finally {
      setPending(false)
    }
  }

  return (
    <div className="panel panel--narrow">
      <h1>Вход</h1>
      <p className="muted">
        Пароля нет: укажите email. Неизвестный email станет покупателем.
      </p>
      <form onSubmit={handleSubmit} className="form">
        <label className="form__field">
          <span>Email</span>
          <input
            type="email"
            required
            value={email}
            autoComplete="email"
            placeholder="buyer1@example.com"
            onChange={(event) => setEmail(event.target.value)}
          />
        </label>
        <button type="submit" className="button" disabled={pending || email.length === 0}>
          {pending ? 'Входим…' : 'Войти'}
        </button>
        {error !== null && <p className="error">{error}</p>}
      </form>
    </div>
  )
}

