  sale: Sale
  soldOut: boolean
  signedIn: boolean
}) {
  return (
    <>
      <button
        type="button"
        className="button button--buy"
        disabled={!canBuy}
        // Резерв появится на следующем шаге; пока кнопка только объясняет это.
        onClick={() => alert('Резерв — на следующем шаге.')}
      >
        Купить
      </button>
      {!canBuy && (
