def ws_client(test_database: str) -> AsyncClient:
    """Клиент с транспортом, умеющим WebSocket поверх ASGI.

    Фикстура синхронная и не входит в `async with` намеренно: anyio привязывает
    cancel scope к задаче, а pytest-asyncio выполняет финализацию асинхронной
    фикстуры отдельной задачей — выход из контекста падал бы с «Attempted to
    exit cancel scope in a different task». Транспорт ASGI сокетов не держит,
    закрывать его не нужно.
    """
    from app.main import app

    return AsyncClient(transport=ASGIWebSocketTransport(app), base_url="http://test")


def find_disconnect(error: BaseException) -> WebSocketDisconnect | None:
    """Достать WebSocketDisconnect из группы исключений.

    `aconnect_ws` работает через группу задач anyio, поэтому ошибка приходит
    завёрнутой в ExceptionGroup.
    """
    if isinstance(error, WebSocketDisconnect):
        return error
    if isinstance(error, BaseExceptionGroup):
        for nested in error.exceptions:
            found = find_disconnect(nested)
            if found is not None:
                return found
    return None

